/**
 * Timeline of the "Chmurka i tęcza" short, derived from the real voiceover word timings
 * (remotion/chmurka/voiceover.json, generated by scripts/tts_chmurka.py).
 *
 * Every scene starts with its voiceover clip; the scene lasts until the last word ends plus a short pause,
 * so pictures, speech and subtitles always stay in sync – even after re-generating the voice.
 */
import voiceover from "./voiceover.json";

export const FPS = 30;
export const WIDTH = 1080;
export const HEIGHT = 1920;

interface RawWord {
  text: string;
  start: number;
  end: number;
}

export interface Word {
  /** Word as displayed (with punctuation from the script). */
  display: string;
  /** Bare word as spoken. */
  bare: string;
  /** Seconds, relative to the scene start. */
  start: number;
  end: number;
  highlight: boolean;
}

export interface Chunk {
  words: Word[];
  /** Seconds, relative to the scene start. */
  start: number;
  end: number;
}

export interface SceneTiming {
  index: number;
  text: string;
  audio: string;
  /** Absolute start in frames. */
  from: number;
  /** Length in frames. */
  frames: number;
  words: Word[];
  chunks: Chunk[];
}

/** Pause after the last word of each scene (s). Scene 3 and 6 get a little extra time for the picture. */
const PAUSE_AFTER = [0.45, 0.45, 0.8, 0.5, 0.55, 0.95];

/** Key words shown in yellow in the subtitles (lower-case, without punctuation). */
const KEY_WORDS = new Set([
  "chmurka",
  "tęcza",
  "tęczę",
  "tęczy",
  "deszczyk",
  "deszczu",
  "kap",
  "kropelek",
  "kropelki",
  "kropelka",
  "słoneczko",
  "lupa",
  "magiczna",
  "światło",
  "kolory",
  "czerwony",
  "pomarańczowy",
  "żółty",
  "zielony",
  "niebieski",
  "fioletowy",
  "za",
  "przed",
]);

const bareOf = (s: string) => s.toLowerCase().replace(/[^\p{L}]/gu, "");

/**
 * Splits a scene into subtitle chunks of (ideally) 2–3 words with a small dynamic programme:
 * single words, chunks that run across a sentence end and very long chunks are penalised,
 * chunks that end on punctuation (a natural pause in speech) are preferred.
 */
export function chunkWords(words: Word[], maxChars = 18): Word[][] {
  const n = words.length;
  const hard = (w: Word) => /[.!?]$/.test(w.display);
  const soft = (w: Word) => /[,:;]$/.test(w.display);
  const cost = (i: number, j: number) => {
    // chunk = words[i..j)
    const ws = words.slice(i, j);
    const chars = ws.map((w) => w.display).join(" ").length;
    if (ws.length > 1 && chars > maxChars) return Infinity;
    let c = ws.length === 1 ? 3 : 0;
    for (const w of ws.slice(0, -1)) c += hard(w) ? 4 : soft(w) ? 1 : 0;
    const last = ws[ws.length - 1];
    if (!hard(last) && !soft(last) && j < n) c += 0.5;
    return c;
  };
  const best: number[] = new Array(n + 1).fill(Infinity);
  const prev: number[] = new Array(n + 1).fill(-1);
  best[0] = 0;
  for (let j = 1; j <= n; j++) {
    for (let k = 1; k <= 3 && j - k >= 0; k++) {
      const c = best[j - k] + cost(j - k, j);
      if (c < best[j]) {
        best[j] = c;
        prev[j] = j - k;
      }
    }
  }
  const out: Word[][] = [];
  for (let j = n; j > 0; j = prev[j]) out.unshift(words.slice(prev[j], j));
  return out;
}

function buildScenes(): SceneTiming[] {
  const scenes: SceneTiming[] = [];
  let from = 0;
  (voiceover as { text: string; words: RawWord[] }[]).forEach((s, index) => {
    const tokens = s.text.split(/\s+/).filter(Boolean);
    if (tokens.length !== s.words.length) {
      throw new Error(`Scene ${index + 1}: ${tokens.length} words in text but ${s.words.length} timings`);
    }
    const words: Word[] = s.words.map((w, i) => ({
      display: tokens[i],
      bare: bareOf(tokens[i]),
      start: w.start,
      end: w.end,
      highlight: KEY_WORDS.has(bareOf(tokens[i])),
    }));
    const groups = chunkWords(words);
    const last = words[words.length - 1].end;
    const sceneEnd = last + PAUSE_AFTER[index];
    const chunks: Chunk[] = groups.map((g, i) => {
      const next = groups[i + 1];
      return {
        words: g,
        start: Math.max(0, g[0].start - 0.08),
        end: next ? next[0].start - 0.08 : Math.min(sceneEnd, g[g.length - 1].end + 0.6),
      };
    });
    const frames = Math.round(sceneEnd * FPS);
    scenes.push({ index, text: s.text, audio: `chmurka/scene${index + 1}.mp3`, from, frames, words, chunks });
    from += frames;
  });
  return scenes;
}

export const SCENES = buildScenes();
export const TOTAL_FRAMES = SCENES.reduce((n, s) => n + s.frames, 0);

/** Start (s, relative to its scene) of the n-th occurrence of a word in a scene. */
export function wordStart(scene: number, bare: string, occurrence = 0): number {
  const hits = SCENES[scene].words.filter((w) => w.bare === bare);
  return (hits[occurrence] ?? hits[hits.length - 1])?.start ?? 0;
}

/** True while any word of the scene is being spoken at local time t (s) – drives Chmurka's mouth. */
export function speakingAt(scene: number, t: number): number {
  for (const w of SCENES[scene].words) {
    if (t >= w.start && t <= w.end) {
      const p = (t - w.start) / Math.max(0.08, w.end - w.start);
      return Math.sin(Math.PI * Math.min(1, p));
    }
  }
  return 0;
}
